import {coreInsideVault,coreVault} from './core-final-vault';
// Their notes, in their vault, at her hand.
//
// The knowledge store reads the vault; nothing let her write to it. "Make a
// note of that" had nowhere to go but her memory, and "what's in my vault"
// had only search to answer with. This is the other half: list a folder,
// read a whole note, add a note or add to one, rewrite one at their word,
// make a folder. Everything is confined to the vault, nothing is deleted,
// and her own folder (Haru/, regenerated by the app) is not for editing by
// hand. Pure over the file system, so a temp directory tests all of it.

import { appendFileSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { DEFAULT_VAULT_SKIP, HARU_FOLDER } from './obsidian';

/** A note longer than this comes back cut, with a word saying so. */
export const NOTE_CAP_CHARS = 20_000;
/** A folder listing stops here. */
export const LIST_CAP = 300;

export type VaultPathVerdict = { ok: true; full: string; relative: string } | { ok: false; error: string };

/** A path inside the vault, or why not: no leaving it, no dotfiles, nothing in her own folder; a note ends in .md. */
export function insideVault(root: string, given: string, kind: 'note' | 'folder'): VaultPathVerdict {
 return coreInsideVault(root,given,kind);
}

export type Listing = { ok: true; folder: string; folders: string[]; notes: { path: string; chars: number; modified: string }[]; more: boolean } | { ok: false; error: string };

/** One folder of the vault: its sub-folders and its notes, newest first. Her own folder is named, not opened. */
export function listVault(root: string, folder = ''): Listing {
 return coreVault('list',root,folder);
}

export type Read = { ok: true; path: string; text: string; chars: number; cut: boolean } | { ok: false; error: string };

export function readNote(root: string, given: string): Read {
 return coreVault('read',root,given);
}

export type WriteMode = 'create' | 'append' | 'replace';
export type Written = { ok: true; path: string; mode: WriteMode; chars: number; existed: boolean; preserved?: true } | { ok: false; error: string; exists?: boolean };

/**
 * A note written. `create` refuses to touch one that exists; `append` adds
 * to it (or starts it); `replace` puts the text in its place — the one mode
 * that loses words, so the tool asks for their word before calling it.
 */
export function writeNote(root: string, given: string, text: string, mode: WriteMode, preserveText = false): Written {
 return coreVault('write',root,given,{text,mode,preserve:preserveText});
}

export type Folder = { ok: true; path: string; existed: boolean } | { ok: false; error: string };

export function createFolder(root: string, given: string): Folder {
 return coreVault('folder',root,given);
}
